package com.example.yuejie;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import java.util.*;import java.io.*;import org.json.*;
/** Exercises the installed reader and restores the original preferences and progress. */
public final class TypographyIntegrationChecks extends DeviceChecks {
 void restore(SharedPreferences prefs,Map<String,?> saved){SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> item:saved.entrySet()){String key=item.getKey();Object v=item.getValue();if(v instanceof String)e.putString(key,(String)v);else if(v instanceof Integer)e.putInt(key,(Integer)v);else if(v instanceof Boolean)e.putBoolean(key,(Boolean)v);else if(v instanceof Float)e.putFloat(key,(Float)v);else if(v instanceof Long)e.putLong(key,(Long)v);else if(v instanceof Set)e.putStringSet(key,new HashSet<>((Set<String>)v));}e.commit();}
 void exercise()throws Exception{
  LocalLibrary library=new LocalLibrary(getTargetContext());List<Book> books=library.books(true);assertTrue(!books.isEmpty(),"existing library");Book selected=books.get(0);JSONObject original=library.progress(selected.id);assertTrue(original!=null,"saved user position");SharedPreferences prefs=getTargetContext().getSharedPreferences("ReaderActivity",0);Map<String,?> saved=new HashMap<>(prefs.getAll());long lastRead;try(android.database.Cursor c=library.getReadableDatabase().rawQuery("SELECT last_read FROM books WHERE id=?",new String[]{selected.id})){c.moveToFirst();lastRead=c.getLong(0);}
  try{
   launchMain();reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",selected.id).putExtra("book_name",selected.title).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();assertTrue(reader.anchor==original.optInt("offset"),"upgrade retains exact original offset");assertTrue(reader.chapter.optString("id").equals(original.optString("chapter")),"upgrade retains chapter");shot("user-current");record("user_position_after_upgrade",new JSONObject().put("chapter",reader.chapter.optString("title")).put("offset",reader.anchor).put("font",reader.settings.font));
   final int anchor=reader.anchor,font=reader.settings.font;ui(()->{reader.settings.font=font<30?font+1:font-1;reader.settingChanged();});ready();ReaderPaginator.Page page=reader.surface.frame.layout.pages.get(reader.surface.frame.pageIndex);assertTrue(reader.anchor==anchor&&page.start<=anchor&&anchor<=page.end,"font reflow retains original anchor");shot("user-font-reflow");ui(()->{reader.settings.font=font;reader.settingChanged();});ready();
   int current=reader.surface.frame.pageIndex;int direction=current+1<reader.surface.frame.layout.pages.size()?1:-1;float w=reader.surface.getWidth(),h=reader.surface.getHeight();touch(w*(direction>0?.88f:.12f),h*.5f,w*(direction>0?.88f:.12f),h*.5f,0,false);waitFor(()->!reader.surface.animating()&&!reader.busy,6,"forward turn");assertTrue(reader.surface.frame.pageIndex==current+direction,"forward page commits");shot("user-next");touch(w*(direction>0?.12f:.88f),h*.5f,w*(direction>0?.12f:.88f),h*.5f,0,false);waitFor(()->!reader.surface.animating()&&!reader.busy,6,"back turn");assertTrue(reader.surface.frame.pageIndex==current,"back returns to original page");record("reflow_and_page_turns",true);
   if(reader.settings.comments){waitFor(()->reader.comments.stats!=null,35,"comment stats");ready();Map<Integer,Long> counts=reader.commentCounts(reader.chapter.optString("id"));assertTrue(reader.surface.frame.layout.commentParagraphs.equals(counts.keySet()),"comments and immutable inline geometry agree");int bubblePage=-1;ReaderPaginator.Fragment selectedPart=null;for(int p=0;p<reader.surface.frame.layout.pages.size()&&bubblePage<0;p++)for(ReaderPaginator.Fragment f:reader.surface.frame.layout.pages.get(p).fragments)if(reader.surface.frame.layout.commentBubble(f)!=null){bubblePage=p;selectedPart=f;break;}assertTrue(bubblePage>=0,"actual chapter has a positive comment entrance");final int p=bubblePage;ReaderSurface.Frame previous=reader.surface.frame;ui(()->reader.commit(new ReaderSurface.Frame(previous.id,previous.title,previous.chapterIndex,previous.totalChapters,previous.layout,p)));RectF rect=reader.surface.frame.layout.commentBubble(selectedPart);int offset=selectedPart.paragraphStart;assertTrue(reader.surface.hitComment(rect.centerX(),rect.centerY())==offset,"hit test consumes the shared bubble geometry");shot("user-comment-entrance");touch(rect.centerX(),rect.centerY(),rect.centerX(),rect.centerY(),0,false);waitFor(()->reader.comments.layer!=null,5,"comment tap");waitFor(()->!reader.comments.loading,35,"comment content");assertTrue(!reader.comments.displayed.isEmpty(),"actual paragraph comments loaded");shot("user-comment-content");ui(()->reader.comments.dismiss());record("inline_comment_tap_and_content",true);}
  }finally{
   if(reader!=null&&!reader.isFinishing())ui(()->reader.finish());restore(prefs,saved);library.progress(selected.id,original.optString("chapter"),original.optInt("offset"),original.optInt("index"),original.optInt("total"),original.optString("title"));ContentValues values=new ContentValues();values.put("last_read",lastRead);library.getWritableDatabase().update("books",values,"id=?",new String[]{selected.id});
  }
  assertTrue(library.progress(selected.id).toString().equals(original.toString()),"original progress restored");assertTrue(prefs.getAll().equals(saved),"all reader preferences restored");assertTrue(library.books(true).size()==books.size(),"books retained");record("preferences_progress_and_books_preserved",true);library.close();
 }
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"typography-integration");output.mkdirs();Bundle result=new Bundle();Throwable error=null;try{exercise();result.putString("stream","PASS\n");}catch(Throwable e){error=e;result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));}try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(output,"results.json")),"UTF-8")){out.write(new JSONObject().put("success",error==null).put("checks",checks).put("error",error==null?JSONObject.NULL:android.util.Log.getStackTraceString(error)).toString(2));}catch(Exception e){error=e;result.putString("stream",e.toString());}finish(error==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
